const mins = (m) => m * 60 * 1000;

function step(role, status, startOffsetMin, durationMinutes) {
  const startedAt = new Date(base + mins(startOffsetMin)).toISOString();
  const completedAt = status === 'pending'
    ? null
    : new Date(base + mins(startOffsetMin + durationMinutes)).toISOString();
  return { role, status, startedAt, completedAt, durationMinutes };
}

