const src = $('Get Company Buying Rules').first().json;
const transactions = Array.isArray(src.workflowLogs) ? src.workflowLogs : [];
const workflowRules = Array.isArray(src.approvalRules) ? src.approvalRules : [];
const policies = Array.isArray(src.policies) ? src.policies : [];

const DELAY_THRESHOLD_MINUTES = 480; // 8 hours

const approvalEvents = [];
for (const tx of transactions) {
  let queueDelayMinutes = 0;
  let prevCompletedOffset = null;
  for (let i = 0; i < (tx.approvalSteps || []).length; i++) {
    const s = tx.approvalSteps[i];
    const isDelayed = (s.durationMinutes || 0) >= DELAY_THRESHOLD_MINUTES;
    const event = {
      transactionId: tx.transactionId,
      department: tx.department,
      category: tx.category,
      amount: tx.amount,
      workflowVersion: tx.workflowVersion,
      role: s.role,
      status: s.status,
      startedAt: s.startedAt,
      completedAt: s.completedAt,
      durationMinutes: s.durationMinutes || 0,
      durationHours: Number(((s.durationMinutes || 0) / 60).toFixed(2)),
      isDelayed,
      stepIndex: i,
      finalStatus: tx.finalStatus,
      reworkCount: tx.reworkCount || 0
    };
    approvalEvents.push(event);
  }
}

const normalizedTransactions = transactions.map((tx) => {
  const steps = tx.approvalSteps || [];
  const totalDurationMinutes = steps.reduce((sum, s) => sum + (s.durationMinutes || 0), 0);
  const approvalDelayMinutes = steps
    .filter((s) => (s.durationMinutes || 0) >= DELAY_THRESHOLD_MINUTES)
    .reduce((sum, s) => sum + (s.durationMinutes || 0), 0);
  return {
    transactionId: tx.transactionId,
    department: tx.department,
    category: tx.category,
    amount: tx.amount,
    workflowVersion: tx.workflowVersion,
    finalStatus: tx.finalStatus,
    reworkCount: tx.reworkCount || 0,
    stepCount: steps.length,
    totalDurationMinutes,
    totalDurationHours: Number((totalDurationMinutes / 60).toFixed(2)),
    approvalDelayMinutes,
    queueDelayMinutes: 0,
    roles: steps.map((s) => s.role)
  };
});

// Fix queue delay: sum of waits between sequential steps approximated as prior step duration for sequential mode
for (const tx of normalizedTransactions) {
  const raw = transactions.find((t) => t.transactionId === tx.transactionId);
  const steps = raw?.approvalSteps || [];
  let queue = 0;
  for (let i = 1; i < steps.length; i++) {
    // In sequential mock data, queue delay is waiting for previous completer — use previous duration as proxy wait contribution already in e2e
    queue += Math.max(0, (steps[i - 1].durationMinutes || 0) * 0.1);
  }
  tx.queueDelayMinutes = Math.round(queue);
  tx.queueDelayHours = Number((tx.queueDelayMinutes / 60).toFixed(2));
}

