const data = $('Clean and Organize the Data').first().json;
const events = data.approvalEvents || [];
const DELAY_THRESHOLD_MINUTES = data.delayThresholdMinutes || 480;

function median(nums) {
  if (!nums.length) return 0;
  const sorted = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}

function avg(nums) {
  if (!nums.length) return 0;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

const byRole = {};
for (const e of events) {
  if (!byRole[e.role]) {
    byRole[e.role] = {
      role: e.role,
      durations: [],
      rejectionCount: 0,
      delayCount: 0,
      totalApprovals: 0,
      totalProcessingMinutes: 0
    };
  }
  const r = byRole[e.role];
  if (e.status === 'approved' || e.status === 'rejected') {
    r.totalApprovals += 1;
    r.durations.push(e.durationMinutes || 0);
    r.totalProcessingMinutes += e.durationMinutes || 0;
  }
  if (e.status === 'rejected') r.rejectionCount += 1;
  if (e.isDelayed) r.delayCount += 1;
}

const roleStats = Object.values(byRole).map((r) => {
  const averageDuration = avg(r.durations);
  const medianDuration = median(r.durations);
  const minDuration = r.durations.length ? Math.min(...r.durations) : 0;
  const maxDuration = r.durations.length ? Math.max(...r.durations) : 0;
  const volume = r.totalApprovals;
  const rejectionRate = volume ? r.rejectionCount / volume : 0;
  const delayRate = volume ? r.delayCount / volume : 0;
  return {
    role: r.role,
    totalApprovals: volume,
    averageDurationMinutes: Number(averageDuration.toFixed(1)),
    averageHours: Number((averageDuration / 60).toFixed(2)),
    medianDurationMinutes: Number(medianDuration.toFixed(1)),
    medianHours: Number((medianDuration / 60).toFixed(2)),
    minimumDurationMinutes: minDuration,
    maximumDurationMinutes: maxDuration,
    approvalVolume: volume,
    rejectionCount: r.rejectionCount,
    rejectionRate: Number(rejectionRate.toFixed(4)),
    delayCount: r.delayCount,
    delayRate: Number(delayRate.toFixed(4)),
    totalProcessingTimeMinutes: r.totalProcessingMinutes,
    totalProcessingTimeHours: Number((r.totalProcessingMinutes / 60).toFixed(2))
  };
});

// Normalize metrics 0-100 across roles
const maxAvg = Math.max(...roleStats.map((r) => r.averageDurationMinutes), 1);
const maxDelay = Math.max(...roleStats.map((r) => r.delayRate), 0.0001);
const maxRej = Math.max(...roleStats.map((r) => r.rejectionRate), 0.0001);
const maxVol = Math.max(...roleStats.map((r) => r.approvalVolume), 1);

const bottlenecks = roleStats.map((r) => {
  const normalizedAverageDuration = (r.averageDurationMinutes / maxAvg) * 100;
  const normalizedDelayRate = (r.delayRate / maxDelay) * 100;
  const normalizedRejectionRate = (r.rejectionRate / maxRej) * 100;
  const normalizedVolume = (r.approvalVolume / maxVol) * 100;
  const bottleneckScore = Math.round(
    normalizedAverageDuration * 0.40 +
    normalizedDelayRate * 0.30 +
    normalizedRejectionRate * 0.20 +
    normalizedVolume * 0.10
  );
  return {
    ...r,
    normalizedAverageDuration: Number(normalizedAverageDuration.toFixed(1)),
    normalizedDelayRate: Number(normalizedDelayRate.toFixed(1)),
    normalizedRejectionRate: Number(normalizedRejectionRate.toFixed(1)),
    normalizedVolume: Number(normalizedVolume.toFixed(1)),
    bottleneckScore
  };
}).sort((a, b) => b.bottleneckScore - a.bottleneckScore);

const primaryBottleneck = bottlenecks[0]?.role || null;

return [{
  json: {
    ...data,
    bottlenecks,
    primaryBottleneck,
    bottleneckFormula: 'normalizedAverageDuration*0.40 + normalizedDelayRate*0.30 + normalizedRejectionRate*0.20 + normalizedVolume*0.10',
    analyzedAt: new Date().toISOString()
  }
}];

const data = $('Find What Is Slowing Approvals').first().json;
const txs = data.transactions || [];
const bottlenecks = data.bottlenecks || [];

function median(nums) {
  if (!nums.length) return 0;
  const sorted = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];
}

const e2eHours = txs.map((t) => t.totalDurationHours || 0);
const avgE2E = e2eHours.length ? e2eHours.reduce((a, b) => a + b, 0) / e2eHours.length : 0;
const medE2E = median(e2eHours);
const rejected = txs.filter((t) => t.finalStatus === 'rejected').length;
const rejectionRate = txs.length ? rejected / txs.length : 0;
const reworked = txs.filter((t) => (t.reworkCount || 0) > 0).length;
const reworkRate = txs.length ? reworked / txs.length : 0;

const primary = bottlenecks[0] || null;
const primaryScore = primary?.bottleneckScore || 0;

const AVG_APPROVAL_THRESHOLD_HOURS = 16;
const HIGH_REJECTION = 0.10;
const HIGH_REWORK = 0.15;

let optimizationOpportunity = 'LOW';
if (primaryScore >= 70 || avgE2E > AVG_APPROVAL_THRESHOLD_HOURS || data.policyChanged || rejectionRate >= HIGH_REJECTION || reworkRate >= HIGH_REWORK) {
  optimizationOpportunity = 'HIGH';
} else if (primaryScore >= 50 || avgE2E > 12) {
  optimizationOpportunity = 'MEDIUM';
}

const optimizationNeeded =
  primaryScore >= 70 ||
  avgE2E > AVG_APPROVAL_THRESHOLD_HOURS ||
  !!data.policyChanged ||
  rejectionRate >= HIGH_REJECTION ||
  reworkRate >= HIGH_REWORK ||
  optimizationOpportunity === 'HIGH';

const metrics = {
  totalTransactions: txs.length,
  averageEndToEndApprovalHours: Number(avgE2E.toFixed(2)),
  medianEndToEndApprovalHours: Number(medE2E.toFixed(2)),
  averageApprovalTimeHours: Number(avgE2E.toFixed(2)),
  medianApprovalTimeHours: Number(medE2E.toFixed(2)),
  approvalDelayHours: Number((txs.reduce((s, t) => s + ((t.approvalDelayMinutes || 0) / 60), 0) / Math.max(txs.length, 1)).toFixed(2)),
  queueDelayHours: Number((txs.reduce((s, t) => s + ((t.queueDelayMinutes || 0) / 60), 0) / Math.max(txs.length, 1)).toFixed(2)),
  rejectionRate: Number(rejectionRate.toFixed(4)),
  reworkRate: Number(reworkRate.toFixed(4)),
  approvalVolume: txs.length,
  currentWorkflowVersion: data.currentWorkflowVersion || 'v3',
  primaryBottleneck: data.primaryBottleneck,
  primaryBottleneckScore: primaryScore,
  optimizationOpportunity,
  optimizationNeeded,
  thresholds: {
    bottleneckScore: 70,
    averageApprovalHours: AVG_APPROVAL_THRESHOLD_HOURS,
    rejectionRate: HIGH_REJECTION,
    reworkRate: HIGH_REWORK
  }
};

return [{
  json: {
    ...data,
    metrics,
    optimizationNeeded,
    calculatedAt: new Date().toISOString()
  }
}];

const data = $('Score Overall Approval Performance').first().json;
const msg = {
  status: 'NO_OPTIMIZATION_REQUIRED',
  message: 'No optimization required — workflow performance and policies are within acceptable thresholds.',
  workflowId: data.workflowId,
  currentWorkflowVersion: data.currentWorkflowVersion,
  primaryBottleneck: data.primaryBottleneck,
  primaryBottleneckScore: data.metrics?.primaryBottleneckScore,
  optimizationOpportunity: data.metrics?.optimizationOpportunity,
