const data = $('Score Overall Approval Performance').first().json;

const mandatoryRoles = new Set();
for (const p of data.policies || []) {
  if (!p.active) continue;
  for (const r of (p.rules?.mandatoryRoles || [])) mandatoryRoles.add(r);
}
for (const rule of data.workflowRules || []) {
  if (!rule.active) continue;
  for (const r of (rule.mandatoryRoles || [])) mandatoryRoles.add(r);
}

const transactionPatterns = {
  byDepartment: {},
  byCategory: {},
  amountBands: { under1k: 0, from1kTo10k: 0, over10k: 0 }
};
for (const t of data.transactions || []) {
  transactionPatterns.byDepartment[t.department] = (transactionPatterns.byDepartment[t.department] || 0) + 1;
  transactionPatterns.byCategory[t.category] = (transactionPatterns.byCategory[t.category] || 0) + 1;
  if (t.amount < 1000) transactionPatterns.amountBands.under1k += 1;
  else if (t.amount < 10000) transactionPatterns.amountBands.from1kTo10k += 1;
  else transactionPatterns.amountBands.over10k += 1;
}

const currentSteps = (data.workflowRules || [])
  .filter((r) => r.active)
  .map((r) => ({
    ruleId: r.ruleId,
