function extractJson(raw) {
  if (raw == null) throw new Error('Empty AI response');
  if (typeof raw === 'object' && !Array.isArray(raw)) {
    if (raw.recommendationId || raw.proposedWorkflow || raw.changes) return raw;
    if (raw.recommendationPreview && (raw.recommendationPreview.recommendationId || raw.recommendationPreview.changes)) {
      return raw.recommendationPreview;
    }
    if (raw.message?.content) return extractJson(raw.message.content);
    if (raw.text) return extractJson(raw.text);
    if (raw.output) return extractJson(raw.output);
    if (raw.content) return extractJson(raw.content);
    // langchain sometimes nests choices
    if (raw.choices?.[0]?.message?.content) return extractJson(raw.choices[0].message.content);
  }
  let s = String(raw).trim();
  // Remove markdown code fences: ```json ... ```
  if (s.startsWith('```')) {
    s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/,'');
  }
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('OpenAI response did not contain a JSON object');
  return JSON.parse(s.slice(start, end + 1));
}

