function inferMode(recommendation) {
  const hasParallel = (recommendation.changes || []).some((c) => String(c.action).toUpperCase() === 'PARALLELIZE');
  return hasParallel ? 'parallel_then_sequential' : 'sequential';
}

function buildDiagram(recommendation) {
  const hasParallel = (recommendation.changes || []).some(
    (c) => String(c.action).toUpperCase() === 'PARALLELIZE' &&
      (c.targetRoles || []).includes('Manager') &&
      (c.targetRoles || []).includes('Finance')
  );
  if (hasParallel) {
    return 'Manager ──┐\n          ├──→ Procurement Head\nFinance ──┘';
  }
  return 'Manager → Finance → Procurement Head';
}

function applyProposedRules(currentRules, recommendation) {
  const rules = JSON.parse(JSON.stringify(currentRules || []));
  const hasParallel = (recommendation.changes || []).some(
    (c) => String(c.action).toUpperCase() === 'PARALLELIZE' &&
      (c.targetRoles || []).includes('Manager') &&
      (c.targetRoles || []).includes('Finance')
  );
  if (hasParallel) {
    for (const rule of rules) {
      if ((rule.approvalRoles || []).includes('Manager') && (rule.approvalRoles || []).includes('Finance')) {
        rule.mode = 'parallel';
        rule.parallelGroups = [['Manager', 'Finance']];
        if ((rule.approvalRoles || []).includes('Procurement Head')) {
          rule.mode = 'parallel_then_sequential';
          rule.sequenceAfterParallel = ['Procurement Head'];
        }
      }
    }
  }
  // Apply REORDER / ADD / ROUTE lightly for demo persistence
  for (const ch of (recommendation.changes || [])) {
    const action = String(ch.action || '').toUpperCase();
    if (action === 'ADD' && ch.targetRoles) {
      for (const rule of rules) {
        if (rule.maxAmount === null || rule.maxAmount > 10000) {
          for (const role of ch.targetRoles) {
            if (!rule.approvalRoles.includes(role)) rule.approvalRoles.push(role);
          }
        }
      }
    }
  }
  return rules;
}

